//! Speed test through the tunnel to this VPS. The Owner and Admins stream generated bytes down and
//! upload bytes the VPS only counts. One transfer runs at a time, each is capped in size and time,
//! and each device waits between tests. Nothing is logged or stored: the only state is the running
//! transfer and each device's last start time, in memory for at most one cooldown.
use super::*;
use axum::body::{Body, Bytes};
use futures_util::StreamExt;
use sirinvpn_protocol::{SPEED_TEST_MAX_BYTES, SPEED_TEST_SECONDS, SpeedTestUpload};
use std::convert::Infallible;

/// Clients stop after `SPEED_TEST_SECONDS`; the slack lets queued upload bytes drain.
const TRANSFER_LIMIT: Duration = Duration::from_secs(SPEED_TEST_SECONDS + 7);
const COOLDOWN: Duration = Duration::from_secs(60);
static ZEROS: [u8; 64 * 1024] = [0; 64 * 1024];

#[derive(Default)]
pub(super) struct Limiter {
    running: Option<Running>,
    next_token: u64,
    /// Last start per device certificate and direction (true = upload), dropped after the cooldown.
    started: HashMap<(String, bool), Instant>,
}

struct Running {
    token: u64,
    device: String,
    until: Instant,
}

impl Limiter {
    fn start(&mut self, device: &str, upload: bool, now: Instant) -> Result<u64, ApiError> {
        self.started
            .retain(|_, started| now.duration_since(*started) < COOLDOWN);
        // A device may replace its own transfer: its previous download may not have closed yet.
        // A stalled client holds the slot only until the transfer limit.
        if let Some(running) = &self.running
            && running.until > now
            && running.device != device
        {
            return Err(ApiError::conflict(
                "another device is running a speed test; try again in a few seconds",
            ));
        }
        if let Some(started) = self.started.get(&(device.to_owned(), upload)) {
            let wait = COOLDOWN.saturating_sub(now.duration_since(*started));
            return Err(ApiError::new(
                StatusCode::TOO_MANY_REQUESTS,
                ErrorCode::RateLimited,
                format!(
                    "wait {} seconds before the next speed test",
                    wait.as_secs() + 1
                ),
            ));
        }
        self.next_token += 1;
        self.running = Some(Running {
            token: self.next_token,
            device: device.to_owned(),
            until: now + TRANSFER_LIMIT,
        });
        self.started.insert((device.to_owned(), upload), now);
        Ok(self.next_token)
    }
}

/// Frees the transfer slot when the response body or upload ends, however it ends.
struct Slot {
    limiter: Arc<Mutex<Limiter>>,
    token: u64,
}

impl Drop for Slot {
    fn drop(&mut self) {
        let mut limiter = self.limiter.lock().unwrap_or_else(|e| e.into_inner());
        if limiter
            .running
            .as_ref()
            .is_some_and(|running| running.token == self.token)
        {
            limiter.running = None;
        }
    }
}

/// Saturating the VPS uplink slows every device, so only managers may run it.
async fn start(state: &AppState, caller: &CallerIdentity, upload: bool) -> Result<Slot, ApiError> {
    authorize_device(state, caller, true).await?;
    let token = state
        .speed_test
        .lock()
        .unwrap_or_else(|e| e.into_inner())
        .start(&caller.certificate_fingerprint, upload, Instant::now())?;
    Ok(Slot {
        limiter: state.speed_test.clone(),
        token,
    })
}

/// A small request the client times while a transfer runs, for latency under load.
pub(super) async fn latency_handler(
    State(state): State<AppState>,
    Extension(caller): Extension<CallerIdentity>,
) -> Result<Json<ApiEnvelope<()>>, ApiError> {
    authorize_device(&state, &caller, true).await?;
    Ok(Json(ApiEnvelope::new(())))
}

pub(super) async fn download_handler(
    State(state): State<AppState>,
    Extension(caller): Extension<CallerIdentity>,
) -> Result<Response, ApiError> {
    let slot = start(&state, &caller, false).await?;
    let deadline = tokio::time::Instant::now() + TRANSFER_LIMIT;
    let body = futures_util::stream::unfold((slot, 0u64), move |(slot, sent)| async move {
        (sent < SPEED_TEST_MAX_BYTES && tokio::time::Instant::now() < deadline).then(|| {
            (
                Ok::<_, Infallible>(Bytes::from_static(&ZEROS)),
                (slot, sent + ZEROS.len() as u64),
            )
        })
    });
    Ok((
        [
            (axum::http::header::CONTENT_TYPE, "application/octet-stream"),
            (axum::http::header::CACHE_CONTROL, "no-store"),
        ],
        Body::from_stream(body),
    )
        .into_response())
}

pub(super) async fn upload_handler(
    State(state): State<AppState>,
    Extension(caller): Extension<CallerIdentity>,
    body: Body,
) -> Result<Json<ApiEnvelope<SpeedTestUpload>>, ApiError> {
    let _slot = start(&state, &caller, true).await?;
    let deadline = tokio::time::Instant::now() + TRANSFER_LIMIT;
    let mut body = body.into_data_stream();
    let mut received_bytes = 0u64;
    loop {
        match tokio::time::timeout_at(deadline, body.next()).await {
            Ok(Some(Ok(chunk))) => {
                received_bytes += chunk.len() as u64;
                if received_bytes > SPEED_TEST_MAX_BYTES {
                    return Err(limit_exceeded());
                }
            }
            Ok(None) => break,
            Ok(Some(Err(_))) => return Err(ApiError::invalid("the speed-test upload ended early")),
            Err(_) => return Err(limit_exceeded()),
        }
    }
    Ok(Json(ApiEnvelope::new(SpeedTestUpload { received_bytes })))
}

fn limit_exceeded() -> ApiError {
    ApiError::new(
        StatusCode::PAYLOAD_TOO_LARGE,
        ErrorCode::InvalidInput,
        "the speed-test upload exceeded the VPS's size or time limit",
    )
}

